changeSet.sql:
DO $$
            BEGIN
                UPDATE public.levy_charges
                   SET base_charge_per_unit = 2675.0000
                 WHERE edp_id = 1
                   AND charge_valid_from = DATE '2026-01-01';
                IF NOT FOUND AND EXISTS (SELECT 1 FROM public.levy_charges) THEN
                    RAISE EXCEPTION 'no levy_charges row for edp_id=1, charge_valid_from=2026-01-01';
                END IF;
            END
            $$;

rollback.sql:
DO $$
                BEGIN
                    UPDATE public.levy_charges
                       SET base_charge_per_unit = 2193.6649
                     WHERE edp_id = 1
                       AND charge_valid_from = DATE '2026-01-01';
                    IF NOT FOUND AND EXISTS (SELECT 1 FROM public.levy_charges) THEN
                        RAISE EXCEPTION 'no levy_charges row for edp_id=1, charge_valid_from=2026-01-01';
                    END IF;
                END
                $$;
